<?php require __DIR__.'/bootstrap.php';
if ($_SERVER['REQUEST_METHOD']==='POST') { if (!hash_equals(admin_csrf(),(string)($_POST['csrf_token']??''))) exit('Form expired.'); $id=(int)$_POST['user_id']; $plan=$_POST['plan_code']??'free'; $status=$_POST['status']??'active'; if(!in_array($plan,['free','pro','business'],true)||!in_array($status,['active','paused','cancelled'],true)) exit('Invalid service setting.'); $pdo->prepare('INSERT INTO user_subscriptions (user_id,plan_code,status,updated_by) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE plan_code=VALUES(plan_code),status=VALUES(status),updated_by=VALUES(updated_by),updated_at=CURRENT_TIMESTAMP')->execute([$id,$plan,$status,$admin['id']]); admin_audit($pdo,(int)$admin['id'],'subscription_updated',$id,['plan'=>$plan,'status'=>$status]); header('Location: index.php?saved=1'); exit; }
$stats=$pdo->query("SELECT (SELECT COUNT(*) FROM users) users,(SELECT COUNT(*) FROM railroads) railroads,(SELECT COUNT(*) FROM user_subscriptions WHERE plan_code<>'free' AND status='active') paid")->fetch(PDO::FETCH_ASSOC);
$users=$pdo->query("SELECT u.id,u.first_name,u.last_name,u.email,u.created_at,COALESCE(s.plan_code,'free') plan_code,COALESCE(s.status,'active') status FROM users u LEFT JOIN user_subscriptions s ON s.user_id=u.id ORDER BY u.created_at DESC LIMIT 100")->fetchAll(PDO::FETCH_ASSOC); ?>
<?php include __DIR__.'/../includes/header.php'; ?><title>TrainTote Admin</title></head><body><main class="container py-4"><h1>Operations Admin</h1><p class="text-muted">Users, service access, and platform activity.</p><?php if(isset($_GET['saved'])): ?><div class="alert alert-success">Service access updated.</div><?php endif; ?><div class="row mb-4"><?php foreach(['users'=>'Users','paid'=>'Paid accounts','railroads'=>'Railroads'] as $key=>$label): ?><div class="col-md-4"><div class="card"><div class="card-body"><small><?= $label ?></small><div class="fs-2 fw-bold"><?= $stats[$key] ?></div></div></div></div><?php endforeach;?></div><div class="card"><div class="card-header">Accounts</div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>User</th><th>Joined</th><th>Service</th><th>Update</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?=htmlspecialchars(trim($u['first_name'].' '.$u['last_name']))?></strong><br><small><?=htmlspecialchars($u['email'])?></small></td><td><?=htmlspecialchars($u['created_at'])?></td><td><?=htmlspecialchars($u['plan_code'])?> / <?=htmlspecialchars($u['status'])?></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(admin_csrf())?>"><input type="hidden" name="user_id" value="<?=$u['id']?>"><select name="plan_code" class="form-select form-select-sm"><?php foreach(['free','pro','business'] as $p):?><option <?=$u['plan_code']===$p?'selected':''?>><?=$p?></option><?php endforeach;?></select><select name="status" class="form-select form-select-sm"><?php foreach(['active','paused','cancelled'] as $s):?><option <?=$u['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div></main><?php include __DIR__.'/../includes/footer.php'; ?>
